def decide(observation, tools):
    direct = tools.direct()
    if direct[1] > direct[0]:
        return 1, 'right', {}
    elif direct[0] > direct[1]:
        return 1, 'left', {}
    else:
        view1, view2 = observation['views']
        h1, h2 = view1['heading'], view2['heading']
        if h1 == 90 and h2 == -90:
            return 0, 'right', {}
        elif h1 == -90 and h2 == 90:
            return 0, 'left', {}
        return 0, 'right', {}

